UPDATE SYT0YG_PYUNGA
   SET CHURI_YMD    = CASE WHEN #{churiYmd, jdbcType=VARCHAR} IS NOT NULL AND #{churiYmd, jdbcType=VARCHAR} != ''
                           THEN TO_DATE(REPLACE(#{churiYmd, jdbcType=VARCHAR}, '-', ''), 'YYYYMMDD')
                           ELSE NULL
                      END
     , GYULJE_JM_CD = #{gyuljeJmCd, jdbcType=VARCHAR}
     , AEK          = #{aek, jdbcType=NUMERIC}
     , TAX_AEK      = #{taxAek, jdbcType=NUMERIC}
 WHERE CORP_GR     = #{corpGr, jdbcType=VARCHAR}
   AND YMD         = TO_DATE(REPLACE(#{ymd, jdbcType=VARCHAR}, '-', ''), 'YYYYMMDD')
   AND PYUNGA_JOIN = #{pyungaJoin, jdbcType=VARCHAR}
